#!/usr/bin/env node
/**
 * Build VFS WASM from Rust.
 * Requires: wasm-bindgen-cli  (cargo install wasm-bindgen-cli)
 *        OR wasm-pack         (cargo install wasm-pack)
 *
 * Output: public/runtime/vfs_ram.{js,wasm}
 *
 * NOTE: Do NOT post-process or overwrite anything in public/runtime/snippets/.
 * Those files are generated by wasm-bindgen and must remain intact.
 */

import { execSync, spawnSync } from "child_process";
import { mkdirSync, existsSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");
const out = join(root, "public", "runtime");
const wasmPath = join(
  root,
  "target",
  "wasm32-unknown-unknown",
  "release",
  "vfs.wasm",
);

mkdirSync(out, { recursive: true });

function run(cmd, args, opts = {}) {
  if (Array.isArray(args)) {
    return spawnSync(cmd, args, { cwd: root, stdio: "inherit", ...opts });
  }
  return spawnSync(cmd, { shell: true, cwd: root, stdio: "inherit", ...args });
}

function hasCommand(cmd) {
  return (
    spawnSync(cmd, ["--version"], { shell: true, stdio: "ignore", cwd: root })
      .status === 0
  );
}

// 1. Ensure target is installed
run("rustup", ["target", "add", "wasm32-unknown-unknown"]);

// 2. Cargo build
const build = run("cargo", [
  "build",
  "--target",
  "wasm32-unknown-unknown",
  "--release",
]);
if (build.status !== 0) process.exit(build.status);

if (!existsSync(wasmPath)) {
  console.error("WASM output not found:", wasmPath);
  process.exit(1);
}

// 3. Generate JS bindings — prefer wasm-bindgen-cli, fall back to wasm-pack
if (hasCommand("wasm-bindgen")) {
  execSync(
    `wasm-bindgen "${wasmPath}" --out-dir "${out}" --target web --out-name vfs_ram`,
    { cwd: root, stdio: "inherit" },
  );
} else if (hasCommand("wasm-pack")) {
  const r = run("wasm-pack", [
    "build",
    "--target",
    "web",
    "--out-dir",
    out,
    "--out-name",
    "vfs_ram",
    "--no-opt",
  ]);
  if (r.status !== 0) process.exit(r.status);
} else {
  console.error(
    "Install one of: cargo install wasm-bindgen-cli  OR  cargo install wasm-pack",
  );
  process.exit(1);
}

// !! Do NOT touch snippets/ — wasm-bindgen puts necessary glue code there.

console.log("VFS WASM built →", join(out, "vfs_ram.js"));
